// The run status band (issue #105): one line per active saga run above the
// prompt, and the issue and phase in saga's status-line entry.
//
// Read-only. Every word comes from `scripts/run_status.py summary --all-active`,
// whose `band_line` the script renders once for every harness: the build loop's
// latest pass, the review cycle against its allowance, and how many lenses met
// their bar by the verdict's own rule. The band never recomputes any of it and
// no button here changes the run. The plain fallback on every other harness is
// `run_status.py summary --band`.
//
// - Refreshes after the session starts, every minute, after each main-loop turn
//   completes, and after a Bash call that ran one of saga's or orchestrate's
//   state scripts. A refresh is queued on the clock so it never holds up a turn.
// - With no active run the band passes and the status line is cleared.
// - Plan and Review open the plan viewer (issue #104) and the review findings
//   pane (issue #108) for the first run; those modules answer the press. Record
//   shows the raw record as `run_record.py show` prints it; Hide hides the band
//   for the session.
// - This is the only saga mod that sets saga's status line: the engine keeps
//   one line per plugin, so a second writer would overwrite this one.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { SagaRunStatus } from '../types/index.d.ts'
import { readRunRecordWith, readRunStatusWith } from './run-record.ts'

/** The raw record pane's id, and the `requestId` its `ui.render` hook matches. */
export const RECORD_PANE = 'saga-record'

/** How often the band reads the runs again with nothing else prompting it. */
export const BAND_REFRESH_MS = 60_000

/** A Code block holds at most 10,000 characters; a page of the record stays under it. */
export const RECORD_PAGE_CHARS = 9_000

/** A Bash command that ran a script which writes saga run state. */
const WRITES_RUN_STATE = /\b(run_record|build_loop|review_result|admission|merge_turn|release_step|saga|orchestrate)\.py\b/

const runStatus = atom({ plugin: 'saga', key: 'runStatus' } as const, [])
const bandHidden = atom({ plugin: 'saga', key: 'bandHidden' } as const, false)
const recordView = atom({ plugin: 'saga', key: 'recordView' } as const, null)

/** Saga's status-line entry for the first run: the issue and its phase alone. */
export function statusText(runs: readonly SagaRunStatus[]): string | undefined {
  const run = runs[0]
  if (run === undefined) return undefined
  return run.phase ? `saga #${run.issue} · ${run.phase}` : `saga #${run.issue}`
}

/** A line cut to `columns` cells, an ellipsis marking the cut. */
export function fitLine(line: string, columns: number): string {
  if (columns <= 0) return ''
  const chars = [...line]
  return chars.length <= columns ? line : `${chars.slice(0, columns - 1).join('')}…`
}

/** A record's JSON cut into pages a Code block can hold, breaking at a newline where one is near. */
export function recordPages(json: string, limit = RECORD_PAGE_CHARS): string[] {
  const pages: string[] = []
  let rest = json
  while (rest.length > limit) {
    const cut = rest.lastIndexOf('\n', limit - 1)
    let end = cut > limit / 2 ? cut + 1 : limit
    // Never split a surrogate pair across two pages.
    if (end === limit && /[\uD800-\uDBFF]/.test(rest[end - 1] ?? '')) end -= 1
    pages.push(rest.slice(0, end))
    rest = rest.slice(end)
  }
  pages.push(rest)
  return pages
}

/**
 * Read the runs again and redraw. A read that fails keeps what the band showed:
 * a record caught mid-write must not blank it, and the next refresh retries.
 */
async function refreshBand($: EngineInterface): Promise<void> {
  const cwd = await $.session.cwd()
  const ran = await readRunStatusWith((argv) => $.process.run(argv), $.plugin.root, { repoRoot: cwd, allActive: true })
  if (!ran.ok) return
  const runs = ran.view.runs
  await update($, runStatus, () => runs)
  $.ui.status(statusText(runs))
}

/**
 * The Plan and Review buttons' keys. The plan viewer and the review pane answer
 * a press on these themselves (`BAND_PLAN_ELEMENT`, `BAND_REVIEW_ELEMENT`): a
 * plugin's own `$.command.run` never reaches its own command hook, while a
 * press is raised by the engine and reaches every hook.
 */
export function bandPlanKey(issue: number): string {
  return `band-plan-${issue}`
}

export function bandReviewKey(issue: number): string {
  return `band-review-${issue}`
}

/** The bottom of a press the pane modules answer; it runs only if neither is registered. */
function paneNotLoaded(): void {}

/** Load issue `issue`'s raw run record into the record pane and open it. */
async function openRecord($: EngineInterface, issue: number): Promise<void> {
  const loaded = await readRunRecordWith((argv) => $.process.run(argv), $.plugin.root, issue)
  if (!loaded.ok) {
    $.ui.toast(`saga: could not read the run record for #${issue} (${loaded.reason}): ${loaded.detail}`)
    return
  }
  const pages = recordPages(JSON.stringify(loaded.record, null, 2))
  await update($, recordView, () => ({ issue, pages, page: 0 }))
  await $.ui.open({ id: RECORD_PANE, title: `Run record · #${issue}` })
}

/** Whether a refresh is running, and whether another was asked for while it ran. */
let refreshing = false
let refreshAgain = false

/**
 * Queue a refresh on the clock, so the dispatch that asked is not held up. One
 * runs at a time; requests made meanwhile fold into one more read after it.
 */
function requestRefresh($: EngineInterface): void {
  $.clock.after(0, async () => {
    if (refreshing) {
      refreshAgain = true
      return
    }
    refreshing = true
    try {
      do {
        refreshAgain = false
        await refreshBand($)
      } while (refreshAgain)
    } finally {
      refreshing = false
    }
  })
}

export function registerRunBand(on: On): void {
  on('session.start', { cwd: /^/ }, async ($, e, next) => {
    requestRefresh($)
    $.clock.every(BAND_REFRESH_MS, () => {
      requestRefresh($)
    })
    return next(e)
  })

  // A subagent's turn ending is not the run moving; the main loop's is.
  on('turn.complete', { turnId: /^/ }, async ($, e, next) => {
    if (e.agentId === undefined) requestRefresh($)
    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny === undefined && WRITES_RUN_STATE.test(e.command)) requestRefresh($)
    return ran
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, bandHidden))) return next(e)
    const runs = await read($, runStatus)
    const first = runs[0]
    if (first === undefined) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    const shown = runs.slice(0, Math.max(1, e.props.maxRows - 1))
    return (
      <Box flexDirection="column">
        {shown.map((run) => (
          <Text key={`run-${run.issue}`}>{fitLine(run.band_line, e.props.bodyColumns)}</Text>
        ))}
        <Box key="actions" flexDirection="row" gap={1}>
          <Button key={bandPlanKey(first.issue)} label="Plan" hotkey="p" onPress={paneNotLoaded} />
          <Button key={bandReviewKey(first.issue)} label="Review" hotkey="r" onPress={paneNotLoaded} />
          <Button key="record" label="Record" hotkey="o" onPress={() => openRecord($, first.issue)} />
          <Button key="hide" label="Hide" hotkey="h" onPress={() => update($, bandHidden, () => true)} />
        </Box>
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: RECORD_PANE }, async ($, e) => {
    const { Box, Button, Code, Text } = $.ui.resolve(e)
    const view = await read($, recordView)
    if (view === null) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No run record loaded. Press Record on the saga run band.</Text>
        </Box>
      )
    }
    const page = Math.min(view.page, view.pages.length - 1)
    const turn = (to: number) => update($, recordView, (now) => (now === null ? now : { ...now, page: to }))
    return (
      <Box flexDirection="column">
        <Text dimColor>{`#${view.issue} · run_record.py show · page ${page + 1} of ${view.pages.length}`}</Text>
        <Code source={view.pages[page] ?? ''} language="json" />
        {view.pages.length > 1 && (
          <Box key="pages" flexDirection="row" gap={1}>
            {page > 0 && <Button key="prev" label="Prev" onPress={() => turn(page - 1)} />}
            {page < view.pages.length - 1 && <Button key="next" label="Next" onPress={() => turn(page + 1)} />}
          </Box>
        )}
      </Box>
    )
  })
}

files.types/index.d.ts:
// Saga's state contract for Claude Code mods.
//
// Saga's scripts own its state; a mod only reads it, by running
// `scripts/run_record.py show <issue>` and parsing the JSON it prints. These
// types describe that JSON. The authority is `plugins/saga/scripts/run_record.py`
// (`SCHEMA` and `TOP_LEVEL_KEYS`); when that file adds a record version, this
// contract and `mods/run-record.ts` change with it.
//
// It also declares the session state the saga mods keep (`PluginState`, at the
// end). Self-contained on purpose: no import and no reference, as the engine
// requires of a plugin's `types` file. Every exported name is led by `Saga`.

/** The one record version this contract reads. */
export type SagaRunRecordSchema = 'run_record.v1'

/**
 * One issue's saga run record, as `run_record.py show` prints it. `to_dict`
 * always writes all twelve keys, so every one is required here;
 * `plugins/saga/tests/test_mod_run_record_contract.py` checks this list against
 * `TOP_LEVEL_KEYS`. Fields a newer writer added are kept under the index
 * signature.
 */
export type SagaRunRecord = {
  schema: SagaRunRecordSchema
  issue: number
  repo: string
  created_at: string
  updated_at: string
  admission: Record<string, unknown>
  run_configuration: Record<string, unknown>
  approval_scope: Record<string, unknown>
  roster: unknown[]
  units: unknown[]
  review_cycles: unknown[]
  next_step: string
  [field: string]: unknown
}

/** Why a read did not produce a record. */
export type SagaRunReadFailure =
  /** The script ran and found no record for the issue. */
  | 'no-record'
  /** The record (or the script's loader) names a version this contract does not know. */
  | 'unknown-version'
  /** The script exited 0 but did not print one JSON object. */
  | 'unreadable'
  /** Any other failure, such as running outside a git repository. */
  | 'error'

/** The outcome of reading one run record. A mod shows `detail` rather than guessing. */
export type SagaRunRead =
  | { ok: true; record: SagaRunRecord }
  | { ok: false; reason: SagaRunReadFailure; detail: string }

/** The version token `scripts/run_status.py summary --json` prints. */
export type SagaRunStatusSchema = 'run_status.v1'

/**
 * Where a run's build loop stands (issue #105). One unit is described (`unit`
 * and the iteration fields set) when its worktree is the checkout or it is the
 * only unit that ran the loop; otherwise only the green count is.
 */
export type SagaRunBuildLoop = {
  unit: string | null
  /** The latest iteration's number. */
  pass: number | null
  failing: number | null
  /** Checks that could not execute, never counted as failing. */
  could_not_execute: number | null
  green: boolean | null
  units_total: number
  units_green: number
}

/**
 * The latest code review cycle against its allowance, and how many lenses met
 * their bar by the verdict's own rule (issue #105).
 */
export type SagaRunReviewProgress = {
  unit: string | null
  cycle: number | null
  standard_allowance: number
  escalated_allowance: number
  /** The cycle is past the standard allowance. */
  is_escalated: boolean
  outcome: string | null
  lenses_met: number
  lenses_total: number
  lenses_not_run: number
}

/**
 * One run as `run_status.py summary --json` prints it. The run record supplies
 * `next_step`, `updated_at`, `record_path`, `build_loop` and `review`; the saga
 * envelope supplies `phase`, `plan_path` (as recorded, relative to the
 * checkout) and `plan_file` (absolute). Each is null when its store does not
 * know the run. `band_line` is the status band's line, rendered by the script
 * so every harness shows the same words.
 */
export type SagaRunStatus = {
  issue: number
  repo: string | null
  next_step: string
  updated_at: string | null
  record_path: string | null
  phase: string | null
  plan_path: string | null
  plan_file: string | null
  build_loop: SagaRunBuildLoop | null
  review: SagaRunReviewProgress | null
  band_line: string
}

/** What `run_status.py summary --json` prints. */
export type SagaRunStatusView = {
  schema: SagaRunStatusSchema
  repo_root: string
  runs: SagaRunStatus[]
}

/**
 * One section of a plan as the plan viewer splits it: the frontmatter
 * (`level` 0), or a heading of level 1 to 3 and the text up to the next
 * heading of the same or a higher level. `text` starts with the heading line.
 */
export type SagaPlanSection = {
  level: 0 | 1 | 2 | 3
  title: string
  text: string
}

/** The plan the viewer pane shows: where it is, when it was read, its sections. */
export type SagaPlanView = {
  /** The path as the operator or the run named it. */
  path: string
  /** The file, every link resolved; what an edit's `file_path` is compared with. */
  absPath: string
  /** The checkout a `path:line` reference in the plan is relative to. */
  repoRoot: string
  mtimeMs: number
  sections: SagaPlanSection[]
}

// ---------------------------------------------------------------------------
// The admission review pane (issue #103)
// ---------------------------------------------------------------------------
//
// `scripts/admission.py --dry-run --render json` prints one document of schema
// `admission_review.v1`; the pane draws from it and nothing else. The authority
// is `review_data` in that script. A field the pane does not draw is left
// untyped under the index signatures.

/** The one review document version the pane reads. */
export type SagaAdmissionReviewSchema = 'admission_review.v1'

/** One tier as admission prints it: vendor, model and effort. */
export type SagaAdmissionTier = { vendor: string | null; model: string; effort: string | null }

/** A Jev cell: the text to show, and the state a pane branches on instead of the text. */
export type SagaAdmissionJevCell = {
  cell: string
  state: string
  [field: string]: unknown
}

/** One staffing row: a role, its default, Jev's cell, the tier proposed, and why. */
export type SagaAdmissionStaffingRow = {
  role: string
  vendor: string | null
  default: SagaAdmissionTier | null
  proposed: SagaAdmissionTier | null
  jev: SagaAdmissionJevCell
  why: string
}

/** One lens row. `include` is `always on`, `yes`, `no` or `undeclared`. */
export type SagaAdmissionLensRow = {
  lens: string
  always_on: boolean
  include: string
  reason: string
  /** `band` is `pre-checked`, `consider` or null (issue #110's lens proposal). */
  jev: SagaAdmissionJevCell & { probability: number | null; band?: string | null }
}

/** The tiers an operator may pick: models, efforts, and the pairs the palette allows. */
export type SagaAdmissionPalette = {
  vendor: string
  models: string[]
  efforts: string[]
  effort_ceilings: Record<string, string>
  pairs: { model: string; effort: string }[]
}

/** What `admission.py --render json` prints. */
export type SagaAdmissionReviewData = {
  schema: SagaAdmissionReviewSchema
  issue: number
  repo: string
  pending_questions: string[]
  staffing: { source: string; status: string; rows: SagaAdmissionStaffingRow[] }
  lenses: { source: string; status: string; catalogue_version: string | null; rows: SagaAdmissionLensRow[] }
  /** Null when the bundled tier palette could not be loaded. */
  palette: SagaAdmissionPalette | null
  [field: string]: unknown
}

/** The operator's picks while the pane is open: per role a tier, per conditional lens a decision. */
export type SagaAdmissionSelections = {
  staffing: Record<string, { model: string; effort: string }>
  lenses: Record<string, { include: 'yes' | 'no'; reason: string }>
}

/** The pane's session state: the document it draws, the picks, and the last refusal shown. */
export type SagaAdmissionReview = {
  issue: number
  repo: string | null
  data: SagaAdmissionReviewData
  selections: SagaAdmissionSelections
  error: string | null
}

/** The answers the pane hands to `admission.py --answers -`. */
export type SagaAdmissionAnswers = {
  staffing_overrides: Record<string, { vendor: string; model: string; effort: string }>
  lens_declaration: {
    always_on: string[]
    conditional_applies: Record<string, string>
    conditional_does_not_apply: Record<string, string>
  }
}

/** What `mcp__saga__review_admission` returns to the model. */
export type SagaAdmissionReviewOutcome =
  | { status: 'submitted'; issue: number; answers: SagaAdmissionAnswers; source: 'operator'; summary: string }
  | { status: 'dismissed' | 'timed-out' | 'nothing-to-review' }
  | { status: 'not-placed' | 'unavailable'; reason: string }
  | { status: 'error'; reason: string; exitCode?: number; stderr?: string }

/** The version token `scripts/run_status.py review --json` prints. */
export type SagaReviewViewSchema = 'review_view.v1'

/**
 * Where a lens stands against its bar. `not_run` (the lens did not execute, or
 * the result has no row for a selected lens) and `unscored` (it ran and
 * reported findings but sets no bar) carry no score, so neither can read as a
 * low one.
 */
export type SagaReviewLensState = 'met' | 'not_met' | 'not_run' | 'unscored'

/** One finding as `run_status.py review` prints it; `FINDING_FIELDS` there. */
export type SagaReviewFinding = {
  id: string
  severity: string
  path: string
  line: number | string
  category: string
  dimension: string
  evidence: string
  impact: string
  status: string
  confidence: string
}

/** One lens of the review: its state, why when it has no usable result, and its findings. */
export type SagaReviewLens = {
  lens: string
  state: SagaReviewLensState
  reason: string | null
  /** Only a `met` or `not_met` lens carries its score. */
  derived_overall: number | null
  finding_count: number
  /** The first few findings, most severe first. */
  top: SagaReviewFinding[]
  findings: SagaReviewFinding[]
}

/** The latest review result in one loop of the run record. */
export type SagaReview = {
  unit: string
  cycle: number
  loop: string
  revision: string
  outcome: string
  reason: string | null
  lenses: SagaReviewLens[]
  /** Findings whose lens is not one of `lenses`. */
  unattributed_findings: SagaReviewFinding[]
  advisory_count: number
  duplicate_count: number
}

/** What `run_status.py review --json` prints. `review` is null when no result is recorded. */
export type SagaReviewView = {
  schema: SagaReviewViewSchema
  repo_root: string
  issue: number | null
  record_path: string | null
  legacy_entries: number
  review: SagaReview | null
}

/**
 * The unit row a session is working, as `run_status.py --repo-root <cwd>
 * unit-for --json` prints it under `match` (issue #107). The token-capture mod
 * appends this session's usage to that row through `run_record.py usage add`.
 */
export type SagaUsageTarget = {
  issue: number
  /** The row's identity as `usage add --unit` takes it: `id`, else `name`, else `unit_id`. */
  unit: string
  /** The staffing role the session records: the row's `role`, else `worker` (`merging-worker` in a merge turn). */
  role: string
  /** How the row matched: its worktree, or only its branch. */
  matched_by: 'worktree' | 'branch'
  record_path: string
  /** The record store, passed back as `--store-root` so a write resolves nothing again. */
  store_root: string
  /** More than one row matched; this is the strongest, active and newest. */
  ambiguous: boolean
}

/** What `run_status.py unit-for --json` prints. */
export type SagaUnitForView = {
  schema: SagaRunStatusSchema
  repo_root: string
  branch: string
  match: SagaUsageTarget | null
}

/**
 * Token counts not yet written to the run record, summed per model session:
 * one bucket per session id (a subagent's loop is its own), role, model and
 * effort, the identity of a `usage add` entry. The four counts are the ones a
 * Claude Code `turn.step` result reports.
 */
export type SagaUsageBucket = {
  sessionId: string
  /** The subagent's id, or null on the main thread. */
  agentId: string | null
  role: string
  model: string
  effort: string
  uncachedInput: number
  cacheRead: number
  cacheWrite: number
  output: number
  /** How many model requests the counts sum. */
  steps: number
}

/** The raw run record pane: the record as JSON, cut into pages a Code block can hold. */
export type SagaRecordView = {
  issue: number
  pages: string[]
  page: number
}

/**
 * One role's agent type, as `scripts/role_agent_types.py` prints it: the role's
 * prompt (a saga hosting preamble, then the roles-library file's body) and the
 * model and effort the run is staffed at.
 */
export type SagaRoleAgentType = {
  /** The staffing role (`worker`); the registered type is `saga:<role>`. */
  role: string
  /** The roles library's id for it (`implementer`). */
  role_id: string
  readable_role: string
  prompt_path: string
  prompt: string
  model: string
  effort: string
  /** The resolver's tier source: `operator`, `overlay`, `jev-raise` or `policy`. */
  source: string
  description: string
}

/** What `scripts/role_agent_types.py --json` prints: `saga_role_agent_types.v1`. */
export type SagaRoleAgentTypes = {
  schema: 'saga_role_agent_types.v1'
  /** Whether this checkout has an active run; with none, `types` is empty. */
  active: boolean
  issue: number | null
  types: SagaRoleAgentType[]
  skipped: { role: string; reason: string }[]
  /** A hash of every type's role, tier and prompt; it changes only when one of them does. */
  fingerprint: string
  /** Why no types could be answered, when that is the case. */
  error?: string
}

/** One registered agent type's resolved tier, by its full name (`saga:worker`). */
export type SagaRegisteredAgentType = {
  role: string
  model: string
  effort: string
}

/** What the agent-types mod last registered, kept in the session's state. */
export type SagaAgentTypesState = {
  active: boolean
  issue: number | null
  fingerprint: string
  byType: Record<string, SagaRegisteredAgentType>
}

declare module 'claude-code' {
  interface PluginState {
    saga: {
      /** The plan the `/plan-view` pane shows, or null before one is loaded. */
      planView: SagaPlanView | null
      /** The section shown, by index into `planView.sections`; -1 is the section list. */
      planSelected: number
      /** The page of the shown section, from 0. */
      planPage: number
      /** The admission review pane's state (issue #103), or null when no review is open. */
      admissionReview: SagaAdmissionReview | null
      /** The review the `/review-view` pane shows, or null before one is loaded. */
      reviewView: SagaReviewView | null
      /** The lens whose findings are listed; null is the lens list. */
      reviewLens: string | null
      /** The run record's modification time when `reviewView` was read. */
      reviewMtimeMs: number
      /** The unit this session's usage goes to; null when it works none (or before it is resolved). */
      usageTarget: SagaUsageTarget | null
      /** Usage read from `turn.step` and not yet written through `usage add`. */
      usageQueue: SagaUsageBucket[]
      /** This checkout's active runs as the status band last read them (issue #105). */
      runStatus: SagaRunStatus[]
      /** The operator pressed the band's Hide; it stays hidden for the session. */
      bandHidden: boolean
      /** The raw run record the band's Record button opened, or null. */
      recordView: SagaRecordView | null
      /** What the agent-types mod last registered (issue #106). */
      agentTypes: SagaAgentTypesState
    }
  }
}

files.mods/run-record.ts:
// The shared way a saga mod reads saga state and writes answers back.
//
// Saga's scripts own the run record. A mod never opens the files under
// `.claude/saga/runs/` and never parses prose: it runs
// `python3 <plugin root>/scripts/run_record.py show <issue>` and parses the
// JSON that prints. (One pinned stderr prefix is the single exception; see
// `EXIT_RECORD_ERROR`.) An answer goes back the same way, through a script's
// command line, built with `sagaScriptArgv`.
//
// The engine's validator follows `$` only into functions declared in the same
// file as the hook, never across an import, so nothing here takes `$` itself.
// A closure over `$.process.run` can cross the import, though, so the guarded
// reader lives here once and a mod's hook passes it the runner:
//
//   import { readRunRecordWith } from './run-record.ts'
//
//   const read = await readRunRecordWith((argv) => $.process.run(argv), $.plugin.root, issue)
//
// `readRunRecordWith` owns the catch: `$.process.run` rejects when the command
// cannot start (no `python3` on the session's PATH) or outlasts its timeout (30
// seconds by default), and the reader turns that into reason 'error' so the mod
// falls back to its plain behaviour instead of throwing. No mod writes its own
// try/catch around the run.
//
// A mod's test can drive the real path too: stub the engine's process runner
// with `on('process.run', async (_$, e) => ({ value: { exitCode, stdout, stderr,
// isStdoutTruncated, isStderrTruncated } }))`, see the argv the reader built in
// `e.argv`, and drive the mod's hook. `plugins/saga/tests/test_mod_run_record_contract.py`
// pins what the real script prints and exits with.

import type { ProcessRunResult } from 'claude-code'
import type {
  SagaReviewView,
  SagaReviewViewSchema,
  SagaRunRead,
  SagaRunRecord,
  SagaRunRecordSchema,
  SagaRunStatusSchema,
  SagaRunStatusView,
} from '../types/index.d.ts'

/** The record version this module reads; `SCHEMA` in `scripts/run_record.py`. */
export const KNOWN_SCHEMA: SagaRunRecordSchema = 'run_record.v1'

/** What `$.process.run` resolves to, narrowed to the fields the parser reads. */
export type ProcessResult = Pick<ProcessRunResult, 'exitCode' | 'stdout' | 'stderr' | 'isStdoutTruncated'>

/** `run_record.py show` exits 3 when its loader meets a record version it does not know. */
const EXIT_UNKNOWN_VERSION = 3

/**
 * Exit 2 covers both "no record" and every other loader failure, and the script
 * has no exit code of its own for a missing record, so the start of its stderr
 * message tells them apart. This is the one place the reader matches script
 * text; `test_mod_run_record_contract.py` pins the prefix against the real
 * script (DECISIONS.md, 2026-10-04).
 */
const EXIT_RECORD_ERROR = 2
const NO_RECORD_PREFIX = 'run_record: no record for issue '

/** A script under `scripts/` is named by its file name alone. */
const SCRIPT_NAME = /^[A-Za-z0-9_][A-Za-z0-9_.-]*\.py$/

function requireIssue(issue: number): void {
  if (!Number.isInteger(issue) || issue <= 0) {
    throw new RangeError(`not an issue number: ${issue}`)
  }
}

/**
 * The argv that runs one of saga's scripts. `$.process.run` takes argv with no
 * shell, so nothing here is quoted; a script name that could leave `scripts/`
 * is refused.
 */
export function sagaScriptArgv(pluginRoot: string, script: string, args: readonly string[]): string[] {
  if (!SCRIPT_NAME.test(script) || script.includes('..')) {
    throw new RangeError(`not a saga script name: ${script}`)
  }
  return ['python3', `${pluginRoot}/scripts/${script}`, ...args]
}

/** The argv that prints one issue's run record as JSON. */
export function runRecordShowArgv(pluginRoot: string, issue: number): string[] {
  requireIssue(issue)
  return sagaScriptArgv(pluginRoot, 'run_record.py', ['show', String(issue)])
}

/** The read a mod reports when `$.process.run` rejected, so the script never ran to an exit. */
export function runRecordRunFailed(err: unknown): SagaRunRead {
  const detail = err instanceof Error ? err.message : String(err)
  return { ok: false, reason: 'error', detail: `run_record show did not run: ${detail}` }
}

/** Turn what `run_record.py show` did into a record, or the reason there is none. */
export function parseRunRecordShow(ran: ProcessResult): SagaRunRead {
  const detail = ran.stderr.trim()
  if (ran.exitCode === EXIT_UNKNOWN_VERSION) return { ok: false, reason: 'unknown-version', detail }
  if (ran.exitCode === EXIT_RECORD_ERROR && detail.startsWith(NO_RECORD_PREFIX)) {
    return { ok: false, reason: 'no-record', detail }
  }
  if (ran.exitCode !== 0) return { ok: false, reason: 'error', detail }
  if (ran.isStdoutTruncated) {
    // The engine keeps only the first 4 MiB of standard output; the JSON is cut.
    return { ok: false, reason: 'unreadable', detail: 'run_record show printed more than the engine keeps (4 MiB); the record was cut off' }
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(ran.stdout)
  } catch (err) {
    return { ok: false, reason: 'unreadable', detail: String(err) }
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { ok: false, reason: 'unreadable', detail: 'run_record show did not print a JSON object' }
  }
  const schema = (parsed as { schema?: unknown }).schema
  if (schema !== KNOWN_SCHEMA) {
    return { ok: false, reason: 'unknown-version', detail: `record version ${JSON.stringify(schema)} is not ${KNOWN_SCHEMA}` }
  }
  return { ok: true, record: parsed as SagaRunRecord }
}

/** Runs one argv and resolves to its result; a mod passes `(argv) => $.process.run(argv)`. */
export type ProcessRunner = (argv: string[]) => Promise<ProcessResult>

/**
 * Read one issue's run record through `run`. Never rejects: a run that could
 * not start or timed out, and an issue number that is not one, come back as
 * reason 'error', so every mod keeps its plain fallback without a catch of its own.
 */
export async function readRunRecordWith(run: ProcessRunner, pluginRoot: string, issue: number): Promise<SagaRunRead> {
  try {
    return parseRunRecordShow(await run(runRecordShowArgv(pluginRoot, issue)))
  } catch (err) {
    return runRecordRunFailed(err)
  }
}

// ---------------------------------------------------------------------------
// `run_status.py summary`: the read-only run view (issue #104)
//
// The run record has no plan path and no lifecycle phase; the saga envelope
// does. `scripts/run_status.py summary --json` joins the two, so a mod reads
// both through one script, the same guarded way it reads the record.
// ---------------------------------------------------------------------------

/** The view version this module reads; `SCHEMA` in `scripts/run_status.py`. */
export const KNOWN_RUN_STATUS_SCHEMA: SagaRunStatusSchema = 'run_status.v1'

/** Which runs `run_status.py summary` reports, and from which checkout. */
export type RunStatusQuery = {
  /** The checkout whose saga envelopes are read: the session's directory. */
  repoRoot: string
  /** One issue; left out, the issue the checkout's active saga or `issue/N` branch names. */
  issue?: number
  /** Every run with a next step, the resolved issue first. */
  allActive?: boolean
}

/** The outcome of reading the run view. A mod shows `detail` rather than guessing. */
export type RunStatusRead =
  | { ok: true; view: SagaRunStatusView }
  | { ok: false; reason: 'unknown-version' | 'unreadable' | 'error'; detail: string }

/** The argv that prints the run view as JSON. */
export function runStatusSummaryArgv(pluginRoot: string, query: RunStatusQuery): string[] {
  const args = ['--repo-root', query.repoRoot, 'summary']
  if (query.issue !== undefined) {
    requireIssue(query.issue)
    args.push('--issue', String(query.issue))
  }
  if (query.allActive === true) args.push('--all-active')
  args.push('--json')
  return sagaScriptArgv(pluginRoot, 'run_status.py', args)
}

/** Why a `run_status.py` command produced no view. */
type RunStatusFailure = { ok: false; reason: 'unknown-version' | 'unreadable' | 'error'; detail: string }

type RunStatusObjectRead = { ok: true; value: Record<string, unknown> } | RunStatusFailure

/**
 * The JSON object a `run_status.py` command printed, or why there is none.
 * `command` names it in every detail, as in "run_status summary".
 */
function parseRunStatusObject(ran: ProcessResult, command: string): RunStatusObjectRead {
  const detail = ran.stderr.trim()
  if (ran.exitCode === EXIT_UNKNOWN_VERSION) return { ok: false, reason: 'unknown-version', detail }
  if (ran.exitCode !== 0) return { ok: false, reason: 'error', detail }
  if (ran.isStdoutTruncated) {
    return { ok: false, reason: 'unreadable', detail: `${command} printed more than the engine keeps (4 MiB)` }
  }
  let parsed: unknown
  try {
    parsed = JSON.parse(ran.stdout)
  } catch (err) {
    return { ok: false, reason: 'unreadable', detail: String(err) }
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { ok: false, reason: 'unreadable', detail: `${command} did not print a JSON object` }
  }
  return { ok: true, value: parsed as Record<string, unknown> }
}

/** Turn what `run_status.py summary --json` did into the view, or the reason there is none. */
export function parseRunStatusSummary(ran: ProcessResult): RunStatusRead {
  const parsed = parseRunStatusObject(ran, 'run_status summary')
  if (!parsed.ok) return parsed
  const view = parsed.value
  if (view.schema !== KNOWN_RUN_STATUS_SCHEMA) {
    return {
      ok: false,
      reason: 'unknown-version',
      detail: `run view version ${JSON.stringify(view.schema)} is not ${KNOWN_RUN_STATUS_SCHEMA}`,
    }
  }
  if (!Array.isArray(view.runs)) {
    return { ok: false, reason: 'unreadable', detail: 'run_status summary printed no runs list' }
  }
  return { ok: true, view: view as unknown as SagaRunStatusView }
}

/** Read the run view through `run`. Never rejects, as `readRunRecordWith`. */
export async function readRunStatusWith(
  run: ProcessRunner,
  pluginRoot: string,
  query: RunStatusQuery,
): Promise<RunStatusRead> {
  try {
    return parseRunStatusSummary(await run(runStatusSummaryArgv(pluginRoot, query)))
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err)
    return { ok: false, reason: 'error', detail: `run_status summary did not run: ${detail}` }
  }
}

// ---------------------------------------------------------------------------
// `run_status.py review`: the latest code review, lens by lens (issue #108)
//
// Whether a lens met its bar is the verdict's own rule
// (`review_consensus.lens_outcomes_for_result`); the script applies it and a
// mod shows the answer, never recomputing it.
// ---------------------------------------------------------------------------

/** The view version this module reads; `REVIEW_SCHEMA` in `scripts/run_status.py`. */
export const KNOWN_REVIEW_VIEW_SCHEMA: SagaReviewViewSchema = 'review_view.v1'

/** Which review `run_status.py review` reports, and from which checkout. */
export type ReviewViewQuery = {
  /** The checkout whose run is read: the session's directory. */
  repoRoot: string
  /** One issue; left out, the issue the checkout's active saga or `issue/N` branch names. */
  issue?: number
}

/** The outcome of reading the review view. A mod shows `detail` rather than guessing. */
export type ReviewViewRead =
  | { ok: true; view: SagaReviewView }
  | { ok: false; reason: 'unknown-version' | 'unreadable' | 'error'; detail: string }

/** The argv that prints the latest code review as JSON. */
export function runStatusReviewArgv(pluginRoot: string, query: ReviewViewQuery): string[] {
  const args = ['--repo-root', query.repoRoot, 'review']
  if (query.issue !== undefined) {
    requireIssue(query.issue)
    args.push('--issue', String(query.issue))
  }
  args.push('--json')
  return sagaScriptArgv(pluginRoot, 'run_status.py', args)
}

/** Turn what `run_status.py review --json` did into the view, or the reason there is none. */
export function parseRunStatusReview(ran: ProcessResult): ReviewViewRead {
  const parsed = parseRunStatusObject(ran, 'run_status review')
  if (!parsed.ok) return parsed
  const view = parsed.value
  if (view.schema !== KNOWN_REVIEW_VIEW_SCHEMA) {
    return {
      ok: false,
      reason: 'unknown-version',
      detail: `review view version ${JSON.stringify(view.schema)} is not ${KNOWN_REVIEW_VIEW_SCHEMA}`,
    }
  }
  const review = view.review as { lenses?: unknown } | null | undefined
  if (review === undefined || (review !== null && !Array.isArray(review.lenses))) {
    return { ok: false, reason: 'unreadable', detail: 'run_status review printed no lens list' }
  }
  return { ok: true, view: view as unknown as SagaReviewView }
}

/** Read the review view through `run`. Never rejects, as `readRunRecordWith`. */
export async function readReviewViewWith(
  run: ProcessRunner,
  pluginRoot: string,
  query: ReviewViewQuery,
): Promise<ReviewViewRead> {
  try {
    return parseRunStatusReview(await run(runStatusReviewArgv(pluginRoot, query)))
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err)
    return { ok: false, reason: 'error', detail: `run_status review did not run: ${detail}` }
  }
}

